    return this.vert.length;
  }
  getVert(i) {
    if (i > this.vert.length) {
      console.log("vertex dont exist");
      return;
    }
    return this.vert[i];
  }
  getEdge(v, i) {
    if (v > this.vert.length) {
      console.log("vertex dont exist");
      return;
    }
    return this.edge.v[i];
